protected override void OnPopulateMesh(VertexHelper vh){
 vh.Clear();if(progress<=0||progress>=1)return;var mesh=meshes[(int)Shape];var rect=GetPixelAdjustedRect();float p=progress,enter=Mathf.SmoothStep(0,1,p/.16f),fade=Mathf.SmoothStep(0,1,(1-p)/.35f);float sx=1,sy=1,dy=0,dx=0;
