 float angle=DirectionDegrees*Mathf.Deg2Rad;float cs=Mathf.Cos(angle),sn=Mathf.Sin(angle);
 foreach(var v in mesh.Vertices){float x=(v.x-64)*sx+dx,y=(64-v.y)*sy+dy;var tint=mesh.Tint;tint.a=v.z*enter*fade*Mathf.Clamp01(Opacity);vh.AddVert(new Vector2(rect.center.x+(x*cs-y*sn)*rect.width/128,rect.center.y+(x*sn+y*cs)*rect.height/128),tint,Vector2.zero);}
